import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Two different outlets covering the exact same product launch, lightly reworded.
        String articleA = "Apple unveiled its new iPhone today at a special event in Cupertino "
            + "featuring an improved camera and longer battery life";
        String articleB = "Apple unveiled its new iPhone today at a special event in Cupertino "
            + "with an improved camera and longer battery life";
        // A genuinely unrelated story.
        String articleC = "Scientists announced a breakthrough in fusion energy research that "
            + "could pave the way for cleaner power generation";

        int shingleSize = 3;
        int numHashes = 20;
        int bandSize = 4;
        long seed = 42L; // fixed seed, so this demo's output is identical on every run

        MinHasher minHasher = new MinHasher(numHashes, seed);
        LshIndex lshIndex = new LshIndex(bandSize);

        Set<String> shinglesA = Shingler.shingle(articleA, shingleSize);
        Set<String> shinglesB = Shingler.shingle(articleB, shingleSize);
        Set<String> shinglesC = Shingler.shingle(articleC, shingleSize);

        long[] signatureA = minHasher.computeSignature(shinglesA);
        long[] signatureB = minHasher.computeSignature(shinglesB);
        long[] signatureC = minHasher.computeSignature(shinglesC);

        lshIndex.index("article-A", signatureA);

        Set<String> candidatesForB = lshIndex.findCandidates(signatureB);
        System.out.println("Candidates found for article B (near duplicate of A): " + candidatesForB);
        System.out.println("Article B correctly flags article A as a likely duplicate: " + candidatesForB.contains("article-A"));

        Set<String> candidatesForC = lshIndex.findCandidates(signatureC);
        System.out.println("Candidates found for article C (unrelated story): " + candidatesForC);
        System.out.println("Article C correctly finds no relation to article A: " + candidatesForC.isEmpty());

        Set<String> intersection = new HashSet<>(shinglesA);
        intersection.retainAll(shinglesB);
        Set<String> union = new HashSet<>(shinglesA);
        union.addAll(shinglesB);
        double trueJaccard = (double) intersection.size() / union.size();
        System.out.println("True Jaccard similarity between A and B: " + trueJaccard);
    }
}

// Breaks text into overlapping word shingles, the basic unit MinHash
// similarity is computed over.
class Shingler {
    public static Set<String> shingle(String text, int shingleSize) {
        String[] words = text.toLowerCase().split("\\s+");
        Set<String> shingles = new HashSet<>();
        for (int i = 0; i + shingleSize <= words.length; i++) {
            shingles.add(String.join(" ", Arrays.copyOfRange(words, i, i + shingleSize)));
        }
        return shingles;
    }
}

// Computes a compact MinHash signature for a set of shingles, approximating
// Jaccard similarity between two documents without comparing every shingle.
class MinHasher {
    private final int[] seedsA;
    private final int[] seedsB;

    public MinHasher(int numHashes, long seed) {
        seedsA = new int[numHashes];
        seedsB = new int[numHashes];
        Random random = new Random(seed); // fixed seed, so results are reproducible every run
        for (int i = 0; i < numHashes; i++) {
            seedsA[i] = random.nextInt();
            seedsB[i] = random.nextInt();
        }
    }

    // For each of several independent hash functions, keeps only the
    // minimum hash value seen across every shingle, producing one compact
    // signature that approximates the document's full shingle set.
    public long[] computeSignature(Set<String> shingles) {
        long[] signature = new long[seedsA.length];
        Arrays.fill(signature, Long.MAX_VALUE);
        for (String shingle : shingles) {
            int baseHash = shingle.hashCode();
            for (int i = 0; i < seedsA.length; i++) {
                long hashed = ((long) seedsA[i] * baseHash + seedsB[i]) & 0x7fffffffL;
                signature[i] = Math.min(signature[i], hashed);
            }
        }
        return signature;
    }
}

// Groups articles into buckets by bands of their MinHash signature, so a
// new article only needs comparing against whatever few other articles
// already share at least one of its bands.
class LshIndex {
    private final int bandSize;
    private final Map<String, List<String>> bucketToArticleIds = new HashMap<>();

    public LshIndex(int bandSize) {
        this.bandSize = bandSize;
    }

    public void index(String articleId, long[] signature) {
        for (String bucketKey : bucketKeysFor(signature)) {
            bucketToArticleIds.computeIfAbsent(bucketKey, k -> new ArrayList<>()).add(articleId);
        }
    }

    // Returns every other article sharing at least one band with this
    // signature, a small candidate set rather than the entire corpus.
    public Set<String> findCandidates(long[] signature) {
        Set<String> candidates = new HashSet<>();
        for (String bucketKey : bucketKeysFor(signature)) {
            candidates.addAll(bucketToArticleIds.getOrDefault(bucketKey, Collections.emptyList()));
        }
        return candidates;
    }

    private List<String> bucketKeysFor(long[] signature) {
        List<String> keys = new ArrayList<>();
        for (int i = 0; i < signature.length; i += bandSize) {
            int end = Math.min(i + bandSize, signature.length);
            keys.add(i + "-" + Arrays.toString(Arrays.copyOfRange(signature, i, end)));
        }
        return keys;
    }
}

