// Breaks text into overlapping word shingles, the basic unit MinHash
// similarity is computed over.
class Shingler {
public:
    static std::set<std::string> shingle(const std::string& text, int shingleSize) {
        std::vector<std::string> words;
        std::string lower = text;
        for (auto& c : lower) c = static_cast<char>(::tolower(static_cast<unsigned char>(c)));
        std::istringstream iss(lower);
        std::string w;
        while (iss >> w) words.push_back(w);

        std::set<std::string> shingles;
        for (size_t i = 0; i + shingleSize <= words.size(); i++) {
            std::string joined;
            for (int j = 0; j < shingleSize; j++) {
                if (j) joined += " ";
                joined += words[i + j];
            }
            shingles.insert(joined);
        }
        return shingles;
    }
};

// A 32-bit polynomial string hash (same recurrence used by Java's own
// String.hashCode): deterministic across languages given the same input,
// which is what keeps the MinHash signatures below comparable.
int32_t stringHash(const std::string& s) {
    int32_t h = 0;
    for (unsigned char c : s) h = 31 * h + static_cast<int32_t>(c);
    return h;
}

// A small, fixed linear-congruential generator (not std::mt19937) purely so
// the demo's hash seeds are reproducible byte-for-byte from one run to the next.
class SeededRandom {
public:
    explicit SeededRandom(uint64_t seed) : state_((seed ^ 0x5DEECE66DULL) & ((1ULL << 48) - 1)) {}

    int32_t nextInt() {
        state_ = (state_ * 0x5DEECE66DULL + 0xBULL) & ((1ULL << 48) - 1);
        return static_cast<int32_t>(state_ >> 16);
    }

private:
    uint64_t state_;
};

// Computes a compact MinHash signature for a set of shingles, approximating
// Jaccard similarity between two documents without comparing every shingle.
class MinHasher {
public:
    MinHasher(int numHashes, uint64_t seed) {
        SeededRandom rng(seed);   // fixed seed, so results are reproducible every run
        for (int i = 0; i < numHashes; i++) seedsA_.push_back(rng.nextInt());
        for (int i = 0; i < numHashes; i++) seedsB_.push_back(rng.nextInt());
    }

    // For each of several independent hash functions, keeps only the
    // minimum hash value seen across every shingle, producing one compact
    // signature that approximates the document's full shingle set.
    std::vector<int64_t> computeSignature(const std::set<std::string>& shingles) {
        std::vector<int64_t> signature(seedsA_.size(), -1);
        for (auto& shingle : shingles) {
            int64_t baseHash = stringHash(shingle);
            for (size_t i = 0; i < seedsA_.size(); i++) {
                int64_t hashed = (static_cast<int64_t>(seedsA_[i]) * baseHash + seedsB_[i]) & 0x7fffffffLL;
                signature[i] = signature[i] < 0 ? hashed : std::min(signature[i], hashed);
            }
        }
        return signature;
    }

private:
    std::vector<int32_t> seedsA_;
    std::vector<int32_t> seedsB_;
};

// Groups articles into buckets by bands of their MinHash signature, so a
// new article only needs comparing against whatever few other articles
// already share at least one of its bands.
class LshIndex {
public:
    explicit LshIndex(int bandSize) : bandSize_(bandSize) {}

    void index(const std::string& articleId, const std::vector<int64_t>& signature) {
        for (auto& bucketKey : bucketKeysFor(signature)) bucketToArticleIds_[bucketKey].push_back(articleId);
    }

    // Returns every other article sharing at least one band with this
    // signature, a small candidate set rather than the entire corpus.
    std::set<std::string> findCandidates(const std::vector<int64_t>& signature) {
        std::set<std::string> candidates;
        for (auto& bucketKey : bucketKeysFor(signature)) {
            auto it = bucketToArticleIds_.find(bucketKey);
            if (it != bucketToArticleIds_.end())
                candidates.insert(it->second.begin(), it->second.end());
        }
        return candidates;
    }

private:
    std::vector<std::string> bucketKeysFor(const std::vector<int64_t>& signature) {
        std::vector<std::string> keys;
        for (size_t i = 0; i < signature.size(); i += bandSize_) {
            size_t end = std::min(i + bandSize_, signature.size());
            std::string band = "[";
            for (size_t j = i; j < end; j++) { if (j > i) band += ", "; band += std::to_string(signature[j]); }
            band += "]";
            keys.push_back(std::to_string(i) + "-" + band);
        }
        return keys;
    }

    int bandSize_;
    std::map<std::string, std::vector<std::string>> bucketToArticleIds_;
};

std::string formatSet(const std::set<std::string>& items) {
    std::string s = "[";
    bool first = true;
    for (auto& item : items) { if (!first) s += ", "; s += item; first = false; }
    s += "]";
    return s;
}

int main() {
    std::cout << std::boolalpha;

    // Two different outlets covering the exact same product launch, lightly reworded.
    std::string articleA = "Apple unveiled its new iPhone today at a special event in Cupertino "
        "featuring an improved camera and longer battery life";
    std::string articleB = "Apple unveiled its new iPhone today at a special event in Cupertino "
        "with an improved camera and longer battery life";
    // A genuinely unrelated story.
    std::string articleC = "Scientists announced a breakthrough in fusion energy research that "
        "could pave the way for cleaner power generation";

    int shingleSize = 3;
    int numHashes = 20;
    int bandSize = 4;
    uint64_t seed = 42ULL;

    MinHasher minHasher(numHashes, seed);
    LshIndex lshIndex(bandSize);

    auto shinglesA = Shingler::shingle(articleA, shingleSize);
    auto shinglesB = Shingler::shingle(articleB, shingleSize);
    auto shinglesC = Shingler::shingle(articleC, shingleSize);

    auto signatureA = minHasher.computeSignature(shinglesA);
    auto signatureB = minHasher.computeSignature(shinglesB);
    auto signatureC = minHasher.computeSignature(shinglesC);

    lshIndex.index("article-A", signatureA);

    auto candidatesForB = lshIndex.findCandidates(signatureB);
    std::cout << "Candidates found for article B (near duplicate of A): " << formatSet(candidatesForB) << "\n";
    std::cout << "Article B correctly flags article A as a likely duplicate: " << (candidatesForB.count("article-A") > 0) << "\n";

    auto candidatesForC = lshIndex.findCandidates(signatureC);
    std::cout << "Candidates found for article C (unrelated story): " << formatSet(candidatesForC) << "\n";
    std::cout << "Article C correctly finds no relation to article A: " << candidatesForC.empty() << "\n";

    std::vector<std::string> intersection;
    std::set_intersection(shinglesA.begin(), shinglesA.end(), shinglesB.begin(), shinglesB.end(), std::back_inserter(intersection));
    std::vector<std::string> unionSet;
    std::set_union(shinglesA.begin(), shinglesA.end(), shinglesB.begin(), shinglesB.end(), std::back_inserter(unionSet));
    double trueJaccard = static_cast<double>(intersection.size()) / unionSet.size();
    std::cout << "True Jaccard similarity between A and B: " << std::setprecision(16) << trueJaccard << "\n";
    return 0;
}

